const fs = require('fs');
const buf = fs.readFileSync(0);
let idx = 0;

function nextInt() {
  while (idx < buf.length && buf[idx] <= 32) idx++;
  let num = 0;
  while (idx < buf.length && buf[idx] > 32) {
    num = num * 10 + (buf[idx] - 48);
    idx++;
  }
  return num;
}

const N = nextInt();
const K = nextInt();
const arr = new Int32Array(N);

for (let i = 0; i < N; i++) {
  arr[i] = nextInt();
}

let ans = 0;
let left = 0;
let sum = 0;
let nz = 0;

for (let right = 0; right < N; right++) {
  sum += arr[right];

  while (sum > K) {
    sum -= arr[left];
    left++;
    if (nz < left) nz = left;
  }

  if (sum === K) {
    if (K === 0) {
      ans += right - left + 1;
    } else {
      while (nz <= right && arr[nz] === 0) {
        nz++;
      }
      ans += nz - left + 1;
    }
  }
}

console.log(ans);
